{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-fXSti7/src/policies.js","content":"/**
 * Per-key state machines for the two policy kinds. Each factory closes over
 * a Map from event key to that key's independent state, and exposes
 * advance/allow/record so the simulator can drive every policy on a route
 * identically regardless of kind.
 */

/**
 * A token bucket. Tokens are tracked in units of 1/per of a token so that
 * partial refills never lose precision, using BigInt throughout to stay
 * exact for arbitrarily large counts.
 */
export function createBucket({ capacity, refill, per }) {
  const states = new Map()
  const fullUnits = capacity * per

  function stateFor(key, tick) {
    let state = states.get(key)
    if (!state) {
      state = { units: fullUnits, tick }
      states.set(key, state)
    }
    return state
  }

  return {
    advance(key, tick) {
      const state = stateFor(key, tick)
      const elapsed = tick - state.tick
      if (elapsed > 0n) {
        state.units += refill * elapsed
        if (state.units > fullUnits) state.units = fullUnits
        state.tick = tick
      }
    },
    allow(key) {
      return states.get(key).units >= per
    },
    record(key) {
      states.get(key).units -= per
    },
  }
}

/** A sliding window. Remembers the ticks of recorded requests per key. */
export function createWindow({ limit, span }) {
  const states = new Map()

  function stateFor(key) {
    let state = states.get(key)
    if (!state) {
      state = { ticks: [], tick: 0n }
      states.set(key, state)
    }
    return state
  }

  return {
    advance(key, tick) {
      const state = stateFor(key)
      const threshold = tick - span
      state.ticks = state.ticks.filter((t) => t > threshold)
      state.tick = tick
    },
    allow(key) {
      return BigInt(states.get(key).ticks.length) < limit
    },
    record(key) {
      const state = states.get(key)
      state.ticks.push(state.tick)
    },
  }
}
"}

