{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-fXSti7/src/parse.js","content":"import { ParseError } from './errors.js'
import { createBucket, createWindow } from './policies.js'

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function parseIntField(line, token, field, min) {
  if (!INT_RE.test(token) || BigInt(token) < min) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

function parseBucket(line, tokens, policies) {
  if (tokens.length !== 5) {
    throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
  }
  const [, name, capacityTok, refillTok, perTok] = tokens
  if (!TOKEN_RE.test(name)) throw new ParseError(line, `invalid policy name ${name}`)
  if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
  const capacity = parseIntField(line, capacityTok, 'capacity', 1n)
  const refill = parseIntField(line, refillTok, 'refill', 0n)
  const per = parseIntField(line, perTok, 'per', 1n)
  policies.set(name, createBucket({ capacity, refill, per }))
}

function parseWindow(line, tokens, policies) {
  if (tokens.length !== 4) {
    throw new ParseError(line, 'expected window <name> <limit> <span>')
  }
  const [, name, limitTok, spanTok] = tokens
  if (!TOKEN_RE.test(name)) throw new ParseError(line, `invalid policy name ${name}`)
  if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
  const limit = parseIntField(line, limitTok, 'limit', 0n)
  const span = parseIntField(line, spanTok, 'span', 1n)
  policies.set(name, createWindow({ limit, span }))
}

function parseRoute(line, tokens, policies, routes, routePrefixes) {
  if (tokens.length < 3) {
    throw new ParseError(line, 'expected route <prefix> <policy>...')
  }
  const prefix = tokens[1]
  const policyNames = tokens.slice(2)
  if (!TOKEN_RE.test(prefix)) throw new ParseError(line, `invalid route prefix ${prefix}`)
  if (routePrefixes.has(prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
  for (const name of policyNames) {
    if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
  }
  routePrefixes.add(prefix)
  routes.push({ prefix, policyNames })
}

function parseEvent(line, tokens, events, lastTick) {
  if (tokens.length !== 3) {
    throw new ParseError(line, 'expected event <tick> <key>')
  }
  const [, tickTok, key] = tokens
  const tick = parseIntField(line, tickTok, 'tick', 0n)
  if (!TOKEN_RE.test(key)) throw new ParseError(line, `invalid key ${key}`)
  if (lastTick.value !== null && tick < lastTick.value) {
    throw new ParseError(line, `tick ${tick} is before tick ${lastTick.value}`)
  }
  lastTick.value = tick
  events.push({ tick, key })
}

/**
 * Parses a limiter file into its declared policies, routes and events, or
 * throws a ParseError naming the first offending line.
 */
export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  const lastTick = { value: null }
  let eventSeen = false

  lines.forEach((raw, index) => {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventSeen) {
        throw new ParseError(line, 'declarations must come before the first event')
      }
      if (directive === 'bucket') parseBucket(line, tokens, policies)
      else if (directive === 'window') parseWindow(line, tokens, policies)
      else parseRoute(line, tokens, policies, routes, routePrefixes)
    } else if (directive === 'event') {
      eventSeen = true
      parseEvent(line, tokens, events, lastTick)
    } else {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
  })

  return { policies, routes, events }
}
"}

